mapper.select:
SELECT s.*, c.name AS category_name FROM scenic_spot s JOIN scenic_category c ON c.id=s.category_id
ORDER BY s.published_at DESC, s.id DESC ORDER BY s.recommendation_weight DESC, s.heat_score DESC, s.id DESC ORDER BY s.heat_score DESC, s.recommendation_weight DESC, s.id DESC ORDER BY s.updated_at DESC, s.id DESC ORDER BY s.heat_score DESC, s.recommendation_weight DESC, s.id DESC
LIMIT #{offset}, #{limit}

SELECT * FROM travel_guide
ORDER BY published_at DESC, id DESC ORDER BY recommendation_weight DESC, heat_score DESC, id DESC ORDER BY heat_score DESC, recommendation_weight DESC, id DESC ORDER BY updated_at DESC, id DESC ORDER BY heat_score DESC, id DESC
LIMIT #{offset}, #{limit}

sql.where:
f.is_deleted=0 AND fc.is_deleted=0
 AND f.status=1 
 AND f.status=#{status} 
 AND f.food_category_id=#{categoryId} 

    AND (f.name LIKE CONCAT('%', #{keyword}, '%') OR f.summary LIKE CONCAT('%', #{keyword}, '%'))


    AND JSON_SEARCH(f.flavor_tags, 'one', CONCAT('%', #{flavor}, '%')) IS NOT NULL

mapper.select:
SELECT f.*, fc.name AS category_name FROM food f JOIN food_category fc ON fc.id=f.food_category_id
ORDER BY f.published_at DESC, f.id DESC ORDER BY f.recommendation_weight DESC, f.heat_score DESC, f.id DESC ORDER BY f.heat_score DESC, f.recommendation_weight DESC, f.id DESC ORDER BY f.updated_at DESC, f.id DESC ORDER BY f.heat_score DESC, f.id DESC
LIMIT #{offset}, #{limit}

